const crypto = require('crypto');

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const binary = items[i].binary.data;

  items[i].json = {
    ...items[i].json,
    sourceFileName: binary.fileName,
    sourceDirectory: binary.directory,
    mimeType: binary.mimeType,
    fileType: binary.fileType,
    fileExtension: binary.fileExtension,
    fileSize: binary.fileSize,
    byteLength: buffer.length,
    sha256: crypto
      .createHash('sha256')
      .update(buffer)
      .digest('hex')
  };
}

return items;

return $input.all().map((item, index) => {
  const data = item.json;
  const binary = item.binary.data;

  const extension = binary.fileExtension || data.fileExtension || 'png';

  const timestamp = new Date()
    .toISOString()
    .replace(/[-:]/g, '')
    .replace(/\.\d{3}Z$/, `-${index + 1}Z`);

  const assetFileName =
    `${data.avatarShort}-${data.assetType}-${data.scene}-${timestamp}.${extension}`;

  return {
    json: {
      ...data,
      assetFileName
    },
    binary: item.binary
  };
});

const crypto = require('crypto');

return $input.all().map(item => {
  const imageBinary = item.binary.data;
  const data = item.json;

  const assetId = crypto.randomUUID();

  const storagePath = `avatars/${data.avatar}/${data.assetType}/`;
  const objectPath = `${storagePath}${data.assetFileName}`;

  const fileSize = imageBinary.fileSize
    ? Math.round(parseFloat(imageBinary.fileSize) * 1024 * 1024)
    : 0;

  const canonicalGroup = `${data.avatar}:${data.scene}:${data.assetType}`;

  const sourceFile = {
    name: imageBinary.fileName,
    directory: imageBinary.directory
  };

  const runtime = {
    inputDir: data.inputDir || '/home/node/.n8n-files/inbox',
    processedDir: data.processedDir || '/home/node/.n8n-files/processed',
    duplicatesDir: data.duplicatesDir || '/home/node/.n8n-files/duplicates',
    failedDir: data.failedDir || '/home/node/.n8n-files/failed',
    baseUrl: data.baseUrl || 'http://192.168.0.194:9000'
  };

  const metadata = {
    assetId,
    sha256: data.sha256,

    avatar: data.avatar,
    assetType: data.assetType,
    scene: data.scene,
    version: data.version,

    status: 'raw',
    reviewNotes: null,
    isCanonical: false,
    canonicalGroup,

    workflow: data.workflow,
    model: data.model,
    seed: data.seed,

    createdAt: new Date().toISOString(),

    sourceFile,
    runtime,

    // Top-level copies used by SQL and move nodes.
    source_file_directory: sourceFile.directory,
    source_file_name: sourceFile.name,
    processed_dir: runtime.processedDir,
    duplicates_dir: runtime.duplicatesDir,
    failed_dir: runtime.failedDir,
    base_url: runtime.baseUrl,

    file: {
      name: data.assetFileName,
      mimeType: imageBinary.mimeType,
      size: fileSize,
      extension: imageBinary.fileExtension || data.fileExtension || 'png'
    },

    storage: {
      bucket: 'iacontentcreator-assets',
      path: storagePath
    },

    objectPath,

    generation: {
      tool: 'ComfyUI',
      workflowVersion: 'v1',
      prompt: '',
      negativePrompt: '',
      sampler: '',
      steps: null,
      cfg: null
    },

    tags: [
      data.avatarShort,
      data.scene,
      data.assetType
    ]
  };

  return {
    json: metadata,
    binary: item.binary
  };
});

parameters.query:
SELECT
  EXISTS (
    SELECT 1
    FROM canonical_asset_registry
    WHERE sha256 = '{{ $json.sha256 }}'
  ) AS duplicated_in_db;

