const seen = new Set();

return $input.all().map(item => {
  const data = item.json;

  const duplicatedInDb = data.duplicated_in_db === true;
  const duplicatedInBatch = seen.has(data.sha256);

  if (!duplicatedInBatch) {
    seen.add(data.sha256);
  }

  const duplicated = duplicatedInDb || duplicatedInBatch;

  return {
    json: {
      ...data,
      duplicated,
      duplicateReason: duplicatedInDb
        ? 'database'
        : duplicatedInBatch
          ? 'batch'
          : null
    },
    binary: item.binary
  };
});

const fs = require('fs');
const path = require('path');

const isMissing = value =>
  !value || value === 'undefined' || value === undefined || value === null;

function uniqueTargetPath(targetDir, sourceName) {
  const parsed = path.parse(sourceName);
  let candidate = path.join(targetDir, sourceName);
  let index = 1;

  while (fs.existsSync(candidate)) {
    candidate = path.join(targetDir, `${parsed.name}-${index}${parsed.ext}`);
    index++;
  }

  return candidate;
}

function moveFile(sourcePath, targetPath) {
  try {
    fs.renameSync(sourcePath, targetPath);
  } catch (error) {
    if (error && error.code === 'EXDEV') {
      fs.copyFileSync(sourcePath, targetPath);
      fs.unlinkSync(sourcePath);
    } else {
      throw error;
    }
  }
}

return $input.all().map(item => {
  const sourceDir =
    item.json.source_file_directory ||
    item.json.sourceFile?.directory;

  const sourceName =
    item.json.source_file_name ||
    item.json.sourceFile?.name;

  const targetDir =
    !isMissing(item.json.duplicates_dir) ? item.json.duplicates_dir :
    !isMissing(item.json.runtime?.duplicatesDir) ? item.json.runtime?.duplicatesDir :
    '/home/node/.n8n-files/duplicates';

  if (isMissing(sourceDir) || isMissing(sourceName)) {
    return {
      json: {
        ...item.json,
        moveStatus: 'skipped',
        moveReason: 'Missing source file metadata',
        sourceDir,
        sourceName
      }
    };
  }

  fs.mkdirSync(targetDir, { recursive: true });

  const sourcePath = path.join(sourceDir, sourceName);
  const targetPath = uniqueTargetPath(targetDir, sourceName);

  if (fs.existsSync(sourcePath)) {
    moveFile(sourcePath, targetPath);
    return {
      json: {
        ...item.json,
        moveStatus: 'duplicate',
        movedFrom: sourcePath,
        movedTo: targetPath
      }
    };
  }

  return {
    json: {
      ...item.json,
      moveStatus: 'skipped',
      moveReason: 'Source file not found',
      attemptedSource: sourcePath
    }
  };
});

